class Solution {
public:
    int minimumOperations(std::vector<int>& nums) {
        int left = 0, right = nums.size() - 1;
        long long l_val = nums[left], r_val = nums[right];
        int ops = 0;
        while (left < right) {
            if (l_val == r_val) {
                left++;
                right--;
                l_val = nums[left];
                r_val = nums[right];
            } else if (l_val < r_val) {
                left++;
                l_val += nums[left];
                ops++;
            } else {
                right--;
                r_val += nums[right];
                ops++;
            }
        }
        return ops;
    }
};

